46	        // after normalization (e.g. "   "), and so downstream steps store/return and compare the
47	        // canonical form. OwnerAddress.normalize yields "" for a null or all-whitespace address.
48	        String normalizedAddress = OwnerAddress.normalize(request.getAddress());
