9	/**
10	 * Shared rules for an owner's registration date. The <em>effective</em> registration date is the one
11	 * supplied in the request, or the server's current date when none was supplied; it must always fall on
12	 * a business day, so a Saturday or Sunday is rolled forward to the next Monday. Every value derived from
13	 * the registration date (the stored {@code registrationDate}, the membership number's year segment and
14	 * the per-day create-limit bucket) is computed from this adjusted date.
15	 *
16	 * <p>The per-day owner-count policy also lives here: {@link #DAILY_LIMIT} is the hard cap enforced at
17	 * create time, and {@link #BULK_WARNING_THRESHOLD} is the (lower) count above which a response carries
18	 * a bulk-signup warning. Both tiers are counted against {@link #countOn(LocalDate, OwnerRepository)}.
19	 */
20	final class RegistrationDates {
21	
22	    /** Maximum number of owners that may be created for a single day. */
23	    static final int DAILY_LIMIT = 100;
24	
25	    /** Owners created for a single day beyond which a response carries a bulk-signup warning. */
26	    static final int BULK_WARNING_THRESHOLD = 80;
27	
28	    private RegistrationDates() {
29	    }
30	
31	    /** Count the owners whose stored registration date equals {@code businessDay}. */
32	    static int countOn(LocalDate businessDay, OwnerRepository repository) {
33	        int count = 0;
34	        for (Owner existing : repository.findAll()) {
35	            if (businessDay != null && businessDay.equals(existing.getRegistrationDate())) {
36	                count++;
37	            }
38	        }
39	        return count;
40	    }
41	
42	    /**
43	     * The effective, business-day registration date: {@code supplied} when non-null, otherwise the
44	     * server's current date, rolled forward to the next Monday when it lands on a weekend.
45	     */
46	    static LocalDate effective(LocalDate supplied) {
47	        return toBusinessDay(supplied != null ? supplied : LocalDate.now());
48	    }
49	
50	    /** Roll a weekend date forward to the next Monday; a weekday is returned unchanged. */
51	    static LocalDate toBusinessDay(LocalDate date) {
52	        if (date.getDayOfWeek() == DayOfWeek.SATURDAY) {
53	            return date.plusDays(2);
54	        }
55	        if (date.getDayOfWeek() == DayOfWeek.SUNDAY) {
56	            return date.plusDays(1);
57	        }
58	        return date;
59	    }
60	}
